import{c as a,Q as s,j as i,m as t}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"Capturing audio","description":"","frontmatter":{},"headers":[],"relativePath":"operating/audio.md","filePath":"operating/audio.md","lastUpdated":1793769581000}'),o={name:"operating/audio.md"};function d(n,e,r,c,h,l){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="capturing-audio" tabindex="-1">Capturing audio <a class="header-anchor" href="#capturing-audio" aria-label="Permalink to &quot;Capturing audio&quot;">​</a></h1><p>A stream can carry one audio track per ALSA capture device. Pick the devices in the stream form&#39;s <strong>Audio</strong> block (or set <code>audio.devices</code> over the <a href="./../reference/rest-api">REST API</a>); with several devices and a <strong>Mix filter</strong> such as <code>amix=inputs=2:duration=shortest</code>, they collapse into one track.</p><h2 id="device-names" tabindex="-1">Device names <a class="header-anchor" href="#device-names" aria-label="Permalink to &quot;Device names&quot;">​</a></h2><p>Prefer card names over card numbers: <code>hw:Lyra,0</code> keeps pointing at the same device after it is unplugged and replugged, while <code>hw:4,0</code> follows whichever card the kernel numbers 4 next. The device picker offers numbered entries; edit the saved value to the card name (from <code>/proc/asound/cards</code>) when the card count can change.</p><h2 id="codec" tabindex="-1">Codec <a class="header-anchor" href="#codec" aria-label="Permalink to &quot;Codec&quot;">​</a></h2><p>Opus is the default and the only codec the WebRTC output can carry. AAC works for RTSP and SRT consumers.</p><h2 id="unplugs-stalls-and-recovery" tabindex="-1">Unplugs, stalls, and recovery <a class="header-anchor" href="#unplugs-stalls-and-recovery" aria-label="Permalink to &quot;Unplugs, stalls, and recovery&quot;">​</a></h2><p><code>videonode-sink</code> captures the devices itself, so audio trouble never stalls video:</p><ul><li>While a device is missing or stops delivering samples, its track carries silence. Players that wait on audio keep playing.</li><li>A device that disappears is retried every 500 ms, and one that goes quiet for 2 s is reopened. Real audio returns on its own after a replug, without restarting the stream.</li><li>Stalls and recoveries are logged once per state change (for example <code>audio [0] vncap:CARD=Lyra,DEV=0: missing; sending silence, retrying (No such device)</code>, then <code>live again after 12.3s missing</code>). Xruns, filled silence, and late audio that had to be dropped are summarized in one line at most every 30 s, only when something happened.</li></ul><h2 id="watching-audio-health" tabindex="-1">Watching audio health <a class="header-anchor" href="#watching-audio-health" aria-label="Permalink to &quot;Watching audio health&quot;">​</a></h2><p>Only <code>videonode-sink</code> can tell real samples from the silence it substitutes; the relay sees audio packets either way. On the stream page, each audio track sits under the encoder&#39;s video input with a wire into the encoder. A missing device, or one sending no samples, turns red and becomes the status headline. Xruns or substituted silence in the last 10 s show as amber <code>dropouts</code>. A dotted device name has a tooltip with the outage reason and start time, or the xrun and silence counts. The same view is in the stream&#39;s health:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/streams/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">stream_i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.health.encoder.sink.audio&#39;</span></span></code></pre></div><p>Each entry carries the <code>device</code>, its <code>state</code> (<code>live</code>, <code>stalled</code>, <code>absent</code>, or <code>opening</code>) with <code>since_us</code>, the <code>error</code> behind an absent state (for example <code>No such device</code>), and run totals for <code>xruns</code>, <code>silence_ms</code>, and <code>dropped_ms</code>. The same data streams over the <code>/api/events</code> metrics feed and as the <code>videonode_sink_audio_*</code> Prometheus series; <code>videonode_sink_audio_up == 0</code> is the alert condition.</p><h2 id="lip-sync" tabindex="-1">Lip sync <a class="header-anchor" href="#lip-sync" aria-label="Permalink to &quot;Lip sync&quot;">​</a></h2><p>Video passes through more stages than audio (capture, conversion, compositing), so audio can arrive slightly ahead of the picture. Set <strong>A/V offset (ms)</strong> (<code>audio.offset_ms</code>, ±2000) to correct it: positive values delay audio, negative values delay video. To measure, clap on camera and compare the sound with the frame where your hands meet; 33 ms is one frame at 30 fps.</p>',15)])])}const m=a(o,[["render",d]]);export{u as __pageData,m as default};
